import sys
from collections import defaultdict
from math import gcd
from functools import reduce

def min_vertices(n, numbers):
    def prime_factors(x):
        factors = []
        d = 2
        while d * d <= x:
            while (x % d) == 0:
                factors.append(d)
                x //= d
            d += 1
        if x > 1:
            factors.append(x)
        return factors

    def lcm(a, b):
        return a * b // gcd(a, b)

    def lcm_multiple(numbers):
        return reduce(lcm, numbers)

    def count_divisors(x):
        factors = prime_factors(x)
        factor_counts = defaultdict(int)
        for factor in factors:
            factor_counts[factor] += 1
        count = 1
        for exp in factor_counts.values():
            count *= (exp + 1)
        return count

    total_lcm = lcm_multiple(numbers)
    total_divisors = count_divisors(total_lcm)

    return total_divisors

